export const ITEM_KINDS = ["flight", "hotel", "car_rental", "excursion"] as const;
export type ItemKind = (typeof ITEM_KINDS)[number];

/**
 * One bookable service found on an image.
 *
 * `entity_id` is generated by our code (never by the AI) the moment the
 * extraction is stored. Staff corrections are saved against this id, so a
 * correction keeps pointing at the right item across revisions, and survives
 * the source image being removed.
 */
export type ExtractedItem = {
  entity_id: string;
  kind: ItemKind;
  data: Record<string, unknown>;
};

/** What kind of screen the image's flights came from; null when the image has no flight. */
export type FlightSource = { type: string; confidence: string; reason: string | null };

export type ExtractionResult = {
  items: ExtractedItem[];
  source: FlightSource | null;
};
